questionvariables.text:
/* Each expression looks like one degree but expands to another, or hides a cancellation:
   0: difference of two squares of binomials, looks quadratic, IS linear: 2(a+b)x + a^2 - b^2 (a+b > 0)
   1: difference of two cubes of binomials, looks cubic, IS quadratic: 3(a+b)x^2 + ... (a+b > 0)
   2: product with a cancelling x^2 term, IS cubic: x^3 + a x + a b */
scenario : rand(3);
a : rand(4)+1;
b : rand(5)+1;
rawexpr : if scenario=0 then (x+a)^2-(x-b)^2
          elseif scenario=1 then (x+a)^3-(x-b)^3
          else (x^2+a)*(x+b)-b*x^2;
/* Simplification does not expand powers or products, so rawexpr displays in its unexpanded form */
displayexpr : rawexpr;
degexpr : expand(rawexpr);
deg : hipow(degexpr,x);
ftype_opt : if deg=1 then "linear" elseif deg=2 then "quadratic" else "cubic";
/* Booleans wrapped in is() so each option carries true or false, not an unevaluated equation */
opts : [["linear", is(deg=1), "Linear"],["quadratic", is(deg=2), "Quadratic"],["cubic", is(deg=3), "Cubic"]];
